	'messages:content-not-allowed-here' => 'hil:" $1 " ang kaundan wala ginatugutan sa pahina [[:$2]] sa slot "$3"',
	'messages:confirmleave-warning' => 'hil:Ang paghalin sa sini nga pahina mahimo nga mangin kabangdanan sang imo pagkadula sang bisan ano nga mga pagbag-o nga imo ginhimo.',
	'messages:editpage-invalidcontentmodel-title' => 'hil:Wala ginasuportahan ang modelo sang kaundan',
	'messages:editpage-invalidcontentmodel-text' => 'hil:Ang modelo sang kaundan nga " $1 " wala ginasuportahan.',
	'messages:editpage-notsupportedcontentformat-title' => 'hil:Ang format sang kaundan wala ginasuportahan',
	'messages:editpage-notsupportedcontentformat-text' => 'hil:Ang format sang kaundan $1 wala ginasuportahan sang modelo sang kaundan $2 .',
